\begin{Def}[Differential Privacy~\cite{DR14}] \label{def:dp}
    A randomized mechanism $\mathcal{M}: \mathcal{D} \to \mathcal{Y}$, where $\mathcal{D}$ is the space of input databases and $\mathcal{Y}$ is the space of outputs, is $(\epsilon, \delta)$-differentially private if, for any pair of neighbouring (differing in one record) databases $D\simeq D'$ and any measurable subset $S \subseteq \mathcal{Y}$,
    \begin{equation}
        \prob{\mathcal{M}\left(D\right) \in S} \leq e^\epsilon \prob{\mathcal{M}\left(D'\right) \in S} + \delta.
    \end{equation}
    $\mathcal{M}$ achieves $\epsilon$-\emph{pure differential privacy} when $\delta = 0$. 
\end{Def}

\IfFull{In \emph{local DP}~\cite{DBLP:conf/pods/EvfimievskiGS03, DP} (Definition~\ref{def:local-dp}), each client applies a DP perturbation to their own data before directly submitting it to the data analyst. 
\begin{Def}[Local Differential Privacy]\label{def:local-dp}
    A mechanism $\mathcal{M}: \mathcal{X} \to \mathcal{Y}$ is $(\epsilon, \delta)$-locally differentially private if, for any $x, x'\in \mathcal{X}$ and any measurable subset $S \subseteq \mathcal{Y}$,
    \begin{equation}
        \Pr\left[\mathcal{M}\left(x\right) \in S \right] \leq e^\epsilon \Pr\left[\mathcal{M}\left(x'\right) \in S\right] + \delta.
    \end{equation}
\end{Def}}

