Each intermediate state $\x_t$ in the forward diffusion process is normally distributed, and its distribution can be expressed directly in terms of the original data $\x_0$:
\begin{align*}
    q(\x_t|\x_0) = \mathcal{N}(\x_t; \sqrt{\bar{\alpha}_t}\x_0, (1-\bar{\alpha}_t)\I)
\end{align*}
where $\bar{\alpha}_t = \prod_{i=1}^{t}\alpha_i$ and $\alpha_t = 1 - \beta_t$.
\end{lemma}

\begin{proof}
Recursive expansion of the diffusion process:
\begin{align*}
        \x_t &= \sqrt{1 - \beta_t}\x_{t - 1} + \sqrt{\beta_t}\epsilon_t \\
        &= \sqrt{\alpha_t}\x_{t - 1} + \sqrt{1 - \alpha_t}\epsilon_t \\
        &= \sqrt{\alpha_t}(\sqrt{\alpha_{t-1}}\x_{t - 2} + \sqrt{1 - \alpha_{t-1}}\epsilon_{t-1}) + \sqrt{1 - \alpha_t}\epsilon_t \\
        &= \sqrt{\alpha_t\alpha_{t-1}}\x_{t - 2} + \sqrt{\alpha_t(1 - \alpha_{t-1})}\epsilon_{t-1} + \sqrt{1 - \alpha_t}\epsilon_t \\
        &= \sqrt{\alpha_t\alpha_{t-1}}\x_{t - 2} + \sqrt{\alpha_t - \alpha_t \alpha_{t-1} + 1 - \alpha_t}\epsilon_{t-1:t} && \text{ variances add up and }\epsilon_{t-1:t} \sim \mathcal{N}(0, \I)\\
        &= \sqrt{\alpha_t\alpha_{t-1}}\x_{t - 2} + \sqrt{1 - \alpha_t \alpha_{t-1}}\epsilon_{t-1:t} \\
        &\dots \\
        &= \sqrt{\bar{\alpha}_t}\x_0 + \sqrt{1 - \bar{\alpha}_t}\epsilon_{0:t} && \epsilon_{0:t} \sim \mathcal{N}(0, \I) \\
        &\triangleq \sqrt{\bar{\alpha}_t}\x_0 + \sqrt{1 - \bar{\alpha}_t}\tilde{\epsilon}_t && \text{ where } \tilde{\epsilon}_t \sim \mathcal{N}(0, \I) \text{ is the full noise added to } \x_0\\
\end{align*}
Note, since $\epsilon_{t-1}$ and $\epsilon_t$ are independent standard Gaussians, the noise terms combine into another Gaussian noise term by adding the variance terms within the square root.
Thus, the probability distribution of $\x_t$ conditioned on $\x_0$ is a Gaussian with mean $\sqrt{\bar{\alpha}_t}\x_0$ and covariance $(1-\bar{\alpha}_t)\I$.
\end{proof}

